/**
 * Server action to download the user's personal data as a JSON file.
 *
 * Returns name, email, locale, notification settings, and organization memberships
 * (name + role) so the client can build and download the blob without exposing
 * credentials or internal IDs.
 */
export const downloadUserDataAction = authenticatedActionClient.action(
  withAuditLogging("dataExport", "user", async ({ ctx }) => {
    const user = await getUser(ctx.user.id);
    if (!user) {
      throw new ResourceNotFoundError("user", ctx.user.id);
    }

    // Fetch organization memberships
    const memberships = await prisma.membership.findMany({
      where: {
        userId: ctx.user.id,
        accepted: true,
      },
      select: {
        organization: {
          select: {
            name: true,
          },
        },
        role: true,
      },
    });

    const data = {
      name: user.name,
      email: user.email,
      locale: user.locale,
      notificationSettings: user.notificationSettings,
      organizationMemberships: memberships.map((m) => ({
        organization: m.organization.name,
        role: m.role,
      })),
    };

    return data;
  })
);

